import _ from 'lodash';
import {
    Also, AuthenticationRequiredError,
    RPC_CALL_ENVIRONMENT,
    Coercible,
} from 'civkit/civ-rpc';
import { htmlEscape } from 'civkit/escape';

import type { Context } from 'koa';

import { InjectProperty } from '../services/registry';
import { AsyncLocalContext } from '../services/async-context';

import { TierFeatureConstraintError } from '../services/errors';
import { isIPInNonPublicRange } from '../utils/ip';

@Also({
    openapi: {
        operation: {
            parameters: {
                'Authorization': {
                    description: htmlEscape`Token for authentication.\n\n` +
                        htmlEscape`- Member of <BaseAuthDTO>\n\n` +
                        `- Authorization: Bearer {YOUR_JINA_TOKEN}`
                    ,
                    in: 'header',
                    schema: {
                        anyOf: [
                            { type: 'string', format: 'token' }
                        ]
                    }
                }
            }
        }
    }
})
export class BaseAuthDTO<U extends object = object> extends Coercible {
    uid?: string;
    bearerToken?: string;
    user?: U;

    ip?: string;
    isInternal?: boolean;

    @InjectProperty(AsyncLocalContext)
    ctxMgr!: AsyncLocalContext;

    static override from(input: any) {
        const instance = super.from(input) as BaseAuthDTO;
        instance.isInternal = false;

        const ctx = input[RPC_CALL_ENVIRONMENT] as Context;

        if (ctx) {
            const authorization = ctx.get('authorization');

            if (authorization) {
                const authToken = [REDACTED]' ')[1] || authorization;
                instance.bearerToken = authToken;
            }

            if (ctx.ip) {
                instance.ip = ctx.ip;
                instance.isInternal = ctx.ips.length <= 2 && isIPInNonPublicRange(ctx.ip);
            }
        }

        if (!instance.bearerToken && input._token) {
            instance.bearerToken = [REDACTED];
        }

        return instance;
    }

    async solveUID() {
        if (this.uid) {
            this.ctxMgr.set('uid', this.uid);
            this.ctxMgr.set('bearerToken', this.bearerToken);

            return this.uid;
        }

        if (this.isInternal) {
            return undefined;
        }

        if (this.bearerToken) {
            throw new Error('Not implemented');
        }

        return undefined;
    }

    async assertUID() {
        const uid = await this.solveUID();

        if (!uid) {
            throw new AuthenticationRequiredError('Authentication failed');
        }

        return uid;
    }

    async assertUser() {
        if (this.user) {
            return this.user;
        }

        throw new Error('Not implemented');
    }

    async assertTier(n: number, feature?: string) {
        if (this.isInternal) {
            return true;
        }
        let user;
        try {
            user = await this.assertUser();
        } catch (err) {
            if (err instanceof AuthenticationRequiredError) {
                throw new AuthenticationRequiredError({
                    message: `Authentication is required to use this feature${feature ? ` (${feature})` : ''}. Please provide a valid API key.`
                });
            }

            throw err;
        }

        const tier = user ? 2 : 0;
        if (isNaN(tier) || tier < n) {
            throw new TierFeatureConstraintError({
                message: `Your current plan does not support this feature${feature ? ` (${feature})` : ''}. Please upgrade your plan.`
            });
        }

        return true;
    }
}

import { SerperSearchQueryParams } from '../3rd-party/serper-search';

const tldExtract = require('tld-extract');

function mapDomainQuery(_q: string) {
    let q = _q.toLowerCase();
    if (URL.canParse(q)) {
        const url = new URL(q);
        q = url.hostname;
    }
    let tld;
    try {
        const tldParsed = tldExtract.parse_host(q);
        tld = tldParsed.domain;
    } catch (_err) {
        tld = q;
    }
    if (tld && q === tld) {
        return { path: 'tld', value: tld };
    }

    return { path: 'domain', value: q };
}

export function parseSearchQuery(inputQuery: SerperSearchQueryParams) {
    const q = inputQuery.q || '';
    const chunks = q.trim().split(/\s+/g);
    const query = [];

    const queryMixins: { filter?: any[], should?: any[], must?: any[], mustNot?: any[]; } = {};

    const sites = [];
    const noSites = [];

    for (const x of chunks) {
        const columnIdx = x.indexOf(':');
        if (columnIdx <= 0) {
            query.push(x);
            continue;
        }
        const cmd = x.slice(0, columnIdx).toLowerCase();
        const value = x.slice(columnIdx + 1).trim();

        if (value) {
            if (cmd === 'site') {
                sites.push(value.toLowerCase());
                continue;
            } else if (cmd === '-site') {
                noSites.push(value.toLowerCase());
                continue;
            }
        }

        query.push(x);
    }

    if (sites.length) {
        queryMixins.filter ??= [];
        const mapped = sites.map(mapDomainQuery);
        const tlds = mapped.filter((x) => x.path === 'tld').map((x)=> x.value);
        const domains = mapped.filter((x) => x.path === 'domain').map((x)=> x.value);
        if (tlds.length) {
            queryMixins.filter.push({
                in: {
                    path: 'tld',
                    value: tlds,
                }
            });
        }
        if (domains.length) {
            queryMixins.filter.push({
                in: {
                    path: 'domain',
                    value: domains,
                }
            });
        }
    }
    if (noSites.length) {
        queryMixins.mustNot ??= [];
        queryMixins.mustNot.push(...noSites.map(mapDomainQuery).map((x) => ({ equals: x })));
    }

    // if (inputQuery.gl) {
    //     searchFilter.geolocation = `geolocation:${inputQuery.gl}`;
    // }
    // if (inputQuery.hl) {
    //     searchFilter.language = `language:${inputQuery.hl}`;
    // }

    return {
        query: query.join(' '),
        queryMixins,
    };
}

import { container, singleton } from 'tsyringe';
import { AsyncService } from 'civkit/async-service';
